mapper.select:
SELECT lifecycle_reference_id, event_type, reference_type, region_sido, region_sigungu, lifestyle_level, amount_value, rate_value, numeric_value, reference_year, reference_month, source_name, source_title, source_url, source_type, note, active, created_at, updated_at FROM lifecycle_reference WHERE event_type = #{eventType} AND reference_type = #{referenceType} AND active = TRUE
AND lifestyle_level = #{lifestyleLevel}
AND lifestyle_level IS NULL
AND region_sido = #{regionSido}
AND region_sido IS NULL
AND region_sigungu = #{regionSigungu}
AND region_sigungu IS NULL
ORDER BY reference_year DESC, COALESCE(reference_month, 0) DESC, lifecycle_reference_id DESC
LIMIT 1
